export interface GlyphSpec {
  readonly pathData: string;
  readonly viewBox: string;
}

export interface GlyphProps {
  readonly className?: string;
  readonly width?: string | number;
  readonly height?: string | number;
  readonly attributes?: Readonly<Record<string, string | number | boolean>>;
}

export interface ElementNode {
  tag: string;
  attributes: Record<string, string | number | boolean>;
  children: ElementNode[];
}

export function createGlyphRenderer(
  spec: Readonly<GlyphSpec>,
): (props?: Readonly<GlyphProps>) => ElementNode {
  const pathData = spec.pathData;
  const viewBox = spec.viewBox;

  return (props = {}): ElementNode => {
    const attributes: Record<string, string | number | boolean> = {};
    for (const [key, value] of Object.entries(props.attributes ?? {})) {
      if (key !== 'width' && key !== 'height') attributes[key] = value;
    }
    const extraClass = props.className?.trim();
    if (!('class' in attributes)) attributes.class = extraClass ? `glyph ${extraClass}` : 'glyph';
    attributes.width = props.width ?? '1em';
    attributes.height = props.height ?? '1em';

    return {
      tag: 'span',
      attributes,
      children: [{
        tag: 'svg',
        attributes: { viewBox },
        children: [{ tag: 'path', attributes: { d: pathData }, children: [] }],
      }],
    };
  };
}

