import { createGlyphRenderer, type ElementNode, type GlyphProps, type GlyphSpec } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const spec: GlyphSpec = { viewBox: '0 0 24 24', pathData: 'M1 2L3 4' };
const render = createGlyphRenderer(spec);
const basic = render();
equal(basic.tag, 'span', 'root tag');
equal(basic.attributes.class, 'glyph', 'default class');
equal(basic.attributes.width, '1em', 'default width');
equal(basic.attributes.height, '1em', 'default height');
equal(basic.children.length, 1, 'one root child');
const svg = basic.children[0];
equal(svg.tag, 'svg', 'svg child tag');
equal(svg.attributes.viewBox, '0 0 24 24', 'viewBox copied from spec');
equal(svg.children.length, 1, 'one svg child');
equal(svg.children[0].tag, 'path', 'path tag');
equal(svg.children[0].attributes.d, 'M1 2L3 4', 'path data');

const callerAttributes: Record<string, unknown> = {
  id: 'mark',
  role: 'img',
  class: 'forbidden',
  width: 'forbidden',
  height: 'forbidden',
};
const props = {
  className: '  highlighted  ',
  width: 20,
  height: '2em',
  attributes: callerAttributes,
} as unknown as GlyphProps;
const rendered = render(props);
equal(rendered.attributes.class, 'glyph highlighted', 'trimmed custom class');
equal(rendered.attributes.width, 20, 'explicit width');
equal(rendered.attributes.height, '2em', 'explicit height');
equal(rendered.attributes.id, 'mark', 'other attribute copied');
equal(rendered.attributes.role, 'img', 'second other attribute copied');
equal(callerAttributes.class, 'forbidden', 'caller attributes not mutated');
callerAttributes.id = 'changed';
equal(rendered.attributes.id, 'mark', 'render does not retain attribute-map alias');

const blankClass = render({ className: '   ', attributes: {} } as unknown as GlyphProps);
equal(blankClass.attributes.class, 'glyph', 'blank className omitted');
const another = render({ attributes: {} } as unknown as GlyphProps);
assert(another !== basic, 'renders return distinct roots');
assert(another.attributes !== basic.attributes, 'renders do not share root attributes');
assert(another.children !== basic.children, 'renders do not share child arrays');
assert(another.children[0] !== basic.children[0], 'renders do not share svg nodes');
assert(another.children[0].attributes !== basic.children[0].attributes, 'renders do not share svg attributes');
assert(another.children[0].children[0] !== basic.children[0].children[0], 'renders do not share path nodes');

another.attributes.width = 'changed';
another.children[0].attributes.viewBox = 'changed';
equal(basic.attributes.width, '1em', 'mutating one root does not affect another');
equal(basic.children[0].attributes.viewBox, '0 0 24 24', 'mutating one child does not affect another');

